import{_ as e,o,c as s,a2 as n}from"./chunks/framework.CqdVOxXJ.js";const r="/rakkii-cars-guide/screenshots/01-welcome-and-navigation/01-sign-in.png",a="/rakkii-cars-guide/screenshots/01-welcome-and-navigation/02-hub-switcher.png",i="/rakkii-cars-guide/screenshots/01-welcome-and-navigation/03-branch-switcher.png",d="/rakkii-cars-guide/screenshots/01-welcome-and-navigation/04-job-history.png",y=JSON.parse('{"title":"1. Welcome & navigation","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/01-welcome-and-navigation.md","filePath":"chapters/01-welcome-and-navigation.md","lastUpdated":1793403538000}'),h={name:"chapters/01-welcome-and-navigation.md"};function l(c,t,p,g,u,m){return o(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="_1-welcome-navigation" tabindex="-1">1. Welcome &amp; navigation <a class="header-anchor" href="#_1-welcome-navigation" aria-label="Permalink to &quot;1. Welcome &amp; navigation&quot;">​</a></h1><p>Rakkii Ops is the staff app for Rakkii Cars. It holds every job from first inquiry to release and close, with the money, people and paperwork attached. Customers never sign in here. They use the <strong>Customer Portal</strong> (pay link and <code>/account</code>).</p><table tabindex="0"><thead><tr><th>Environment</th><th>Staff (Ops App)</th><th>Customers (Customer Portal)</th></tr></thead><tbody><tr><td>Integration (practice)</td><td><code>https://rakkii-ops-int.web.app</code></td><td><code>https://rakkii-web-int.web.app</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">How this guide is written</p><p>The look of the app is still being polished. The workflows, page names, tab names, statuses and required fields in this guide do not change with that polish. Follow the <strong>names</strong>, not colours or positions on the screen.</p></div><h2 id="_1-1-who-this-guide-is-for" tabindex="-1">1.1 Who this guide is for <a class="header-anchor" href="#_1-1-who-this-guide-is-for" aria-label="Permalink to &quot;1.1 Who this guide is for&quot;">​</a></h2><p>Every login has exactly one role. The role decides which hubs you see and which buttons work.</p><table tabindex="0"><thead><tr><th>Role (app label)</th><th>Role key</th><th>Hubs</th><th>What you do</th><th>Read</th></tr></thead><tbody><tr><td><strong>Shop Owner</strong></td><td><code>owner</code></td><td>Workshop, Sales, Finance, HR, Admin, Me</td><td>Runs the whole shop: jobs, money, P&amp;L, payroll, settings, staff permissions, release overrides</td><td>Ch. 1, 5–13</td></tr><tr><td><strong>Lead Technician</strong></td><td><code>technician</code></td><td>Workshop, Me</td><td>Works assigned jobs: bay checklist, QC photos, holds, surrendered parts, canvass/parts buy when allowed</td><td>Ch. 1–3</td></tr><tr><td><strong>Sales Agent</strong></td><td><code>sales</code></td><td>Sales, Me</td><td>Brings in customers: pipeline inquiries, follow-ups, monitoring, commission and incentive</td><td>Ch. 1, 3, 4</td></tr><tr><td><strong>Admin / Service Advisor</strong></td><td><code>admin</code></td><td>To be decided — Waiting for confirmation.</td><td>To be decided — Waiting for confirmation.</td><td>—</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Admin in v1</p><p>This version of the guide does not include a dedicated Admin guide. Where an owner step says &quot;owner or admin&quot;, the app also allows the admin role, but the Admin role&#39;s day-to-day scope is <strong>To be decided — Waiting for confirmation.</strong></p></div><h2 id="_1-2-signing-in" tabindex="-1">1.2 Signing in <a class="header-anchor" href="#_1-2-signing-in" aria-label="Permalink to &quot;1.2 Signing in&quot;">​</a></h2><ol><li>Open the Ops App in a browser (phone, tablet or desk computer).</li><li>On <strong>Rakkii Ops sign in</strong>, enter your <strong>Email</strong> and <strong>Password</strong>, then press <strong>Sign in</strong>.</li><li>You land on your role&#39;s home page: <ul><li>Owner → <strong>Workshop › Dashboard</strong> (<code>/workshop</code>)</li><li>Lead Technician → <strong>Workshop › My jobs</strong> (<code>/workshop</code>)</li><li>Sales Agent → <strong>Sales › My pipeline</strong> (<code>/sales/pipeline</code>)</li></ul></li></ol><p>On the integration site only, a <strong>Quick sign-in</strong> box lists test accounts. Pick one, type the <strong>PIN</strong> you were given, and press <strong>Sign in</strong>. Live shops do not show this box.</p><div class="warning custom-block"><p class="custom-block-title">If you see &quot;Access needed&quot; or &quot;no role yet&quot;</p><p>Your account exists but has no role, or the page is outside your role. Ask the Shop Owner to check your role in <strong>Admin › Staff and pay</strong> (Chapter 13). The page links you back to your own home.</p></div><p><img src="'+r+'" alt="Rakkii Ops sign-in page (Email, Password, Sign in)"></p><h2 id="_1-3-the-six-hubs" tabindex="-1">1.3 The six hubs <a class="header-anchor" href="#_1-3-the-six-hubs" aria-label="Permalink to &quot;1.3 The six hubs&quot;">​</a></h2><p>Everything is grouped into hubs. Use the <strong>hub switcher</strong> (the &quot;Switch module&quot; menu in the top bar) to move between them. The app remembers the last hub you used. Each hub has its own side menu.</p><table tabindex="0"><thead><tr><th>Hub</th><th>Path</th><th>What lives there</th><th>Who sees it</th></tr></thead><tbody><tr><td><strong>Workshop</strong></td><td><code>/workshop</code></td><td>Dashboard / My jobs, Shop board, New job, Calendar, Job history, Backjobs, Contractor jobs, Customers, Parts &amp; Inventory, Insurers, Forms</td><td>Owner (all), Technician (My jobs, Calendar, Job history, Forms)</td></tr><tr><td><strong>Sales</strong></td><td><code>/sales</code></td><td>Pipeline, Commission, Monitoring, Incentives, Insurance</td><td>Owner, Sales</td></tr><tr><td><strong>Finance</strong></td><td><code>/finance</code></td><td>Reports, Cash, Accounts, Who owes us, Blanket POs, Payments, Payables, Expenses, Agent fees, Job P&amp;L, Month close, Export</td><td>Owner</td></tr><tr><td><strong>HR</strong></td><td><code>/hr</code></td><td>Directory, Attendance, Leave approvals, Clock kiosk, Documents, Payroll, Announcements</td><td>Owner</td></tr><tr><td><strong>Admin</strong></td><td><code>/admin</code></td><td>Shop settings, Staff and pay</td><td>Owner only</td></tr><tr><td><strong>Me</strong></td><td><code>/me</code></td><td>Time clock, My payslip, Leave, My overtime, My commission, My incentive, My profile</td><td>Everyone (content depends on role)</td></tr></tbody></table><h3 id="workshop-pins" tabindex="-1">Workshop pins <a class="header-anchor" href="#workshop-pins" aria-label="Permalink to &quot;Workshop pins&quot;">​</a></h3><p>When the Workshop hub is open, the owner also gets three pinned shortcuts: <strong>Dashboard</strong>, <strong>Shop board</strong> and <strong>New job</strong>. A technician gets <strong>My jobs</strong>.</p><h3 id="what-each-role-s-menu-looks-like" tabindex="-1">What each role&#39;s menu looks like <a class="header-anchor" href="#what-each-role-s-menu-looks-like" aria-label="Permalink to &quot;What each role&#39;s menu looks like&quot;">​</a></h3><p><strong>Shop Owner</strong> — all six hubs. In <strong>Me</strong>, the owner sees <strong>My payslip</strong> and <strong>My profile</strong> (plus <strong>My commission</strong> / <strong>My incentive</strong> only when they apply). Owners do not clock in or file personal leave; those pages say so.</p><p><strong>Lead Technician</strong> — <strong>Workshop</strong> (My jobs, Calendar, Job history, Forms) and <strong>Me</strong> (Time clock, My payslip, Leave, My overtime, My profile; My commission only if you have commission lines).</p><p><strong>Sales Agent</strong> — <strong>Sales</strong> (My pipeline, My commission, Monitoring, Insurance) and <strong>Me</strong> (Time clock, My payslip, Leave, My overtime, My incentive, My profile).</p><p><img src="'+a+'" alt="hub switcher open, showing Workshop, Sales, Finance, HR, Admin, Me"></p><h2 id="_1-4-owner-switching-the-active-branch" tabindex="-1">1.4 Owner: switching the active branch <a class="header-anchor" href="#_1-4-owner-switching-the-active-branch" aria-label="Permalink to &quot;1.4 Owner: switching the active branch&quot;">​</a></h2><p>Rakkii runs one live shop today (Roosevelt Main), but the app is ready for more. A head-office (HQ) owner can work in any shop they own. A franchise owner pinned to one shop does not get the switcher.</p><p><strong>From the top bar</strong></p><ol><li>Press the shop name in the top bar (<strong>Switch shop branch</strong>). It appears only when you own more than one shop.</li><li>Choose the shop. Every hub now shows that shop&#39;s jobs, money and staff.</li></ol><p><strong>From Shop settings (<code>/admin/settings</code>)</strong></p><ol><li>Go to <strong>Admin › Shop settings</strong>.</li><li>Open the <strong>Company</strong> area, section <strong>Shops</strong>.</li><li>On the shop row, press <strong>Switch to this shop</strong>. The row you are working in is marked <strong>Current</strong>.</li></ol><p>The settings URL keeps your place: <code>/admin/settings?area=shop&amp;section=getting-paid&amp;shop=&lt;shop-code&gt;</code>.</p><div class="warning custom-block"><p class="custom-block-title">Check the shop before you record money</p><p>Payments, expenses and payroll are saved to the <strong>active shop</strong>. Confirm the shop name in the top bar before recording anything.</p></div><p><img src="'+i+'" alt="Shop settings with the Shop picker (the top-bar shop switcher appears only when you own more than one shop)"></p><h2 id="_1-5-dark-mode" tabindex="-1">1.5 Dark mode <a class="header-anchor" href="#_1-5-dark-mode" aria-label="Permalink to &quot;1.5 Dark mode&quot;">​</a></h2><ol><li>Open your account menu (your name in the top bar).</li><li>Press <strong>Dark mode</strong> (or <strong>Light mode</strong> to switch back).</li></ol><p>The choice is saved on that device and also applies to the sign-in page.</p><h2 id="_1-6-finding-things-fast" tabindex="-1">1.6 Finding things fast <a class="header-anchor" href="#_1-6-finding-things-fast" aria-label="Permalink to &quot;1.6 Finding things fast&quot;">​</a></h2><ul><li><strong>Top bar search</strong> (<strong>Plate, job or customer</strong>, press <kbd>/</kbd> to jump to it) finds any job by plate, job reference or customer, open or closed, from any hub.</li><li><strong>Job history</strong> (<code>/workshop/jobs</code>) searches by plate, customer or reference, with <strong>Created from / Created to</strong> dates and a <strong>Status</strong> filter: <strong>All</strong>, <strong>Released · not done</strong> or <strong>Done</strong>. <ul><li><strong>Released · not done</strong> (amber) means the car is out but something is still open, for example an insurer payment. <strong>Done</strong> means nothing is left.</li><li>The <strong>Progress</strong> column shows how far each job is (&quot;6 of 7&quot;). On a phone each job shows as a card.</li></ul></li></ul><p><img src="'+d+'" alt="Job history with Done and Released · not done labels and the Progress column"></p><ul><li>Every job opens in the <strong>job workspace</strong> (<code>/workshop/jobs/:id</code>) with tabs: <strong>Overview, Quote, Canvass, Parts buy, Work, Insurance, Pay, Files, Release</strong>. Some tabs only show when they apply (for example <strong>Insurance</strong> only on insurance jobs; <strong>Canvass</strong> and <strong>Parts buy</strong> only when the job needs them).</li><li>Each job shows a <strong>status banner</strong>, a <strong>steps bar</strong> and a blue <strong>next-step banner</strong> that says what to do now (<a href="/rakkii-cars-guide/chapters/05-lane-1-private-walk-in-jobs#progress">Chapter 5</a>).</li><li>Prints open the print dialog on a computer. On a phone they save as a PDF named after the paper and plate (<a href="/rakkii-cars-guide/chapters/05-lane-1-private-walk-in-jobs#printing">Chapter 5</a>).</li><li>Actions that are hard to undo (create a quote, post an invoice, record a payment, release a car, approve leave) ask you to confirm first.</li><li>Old bookmarks such as <code>/board</code>, <code>/clock</code> or <code>/ops/jobs</code> still open: they redirect to the hub path.</li></ul><h2 id="_1-7-words-you-will-see" tabindex="-1">1.7 Words you will see <a class="header-anchor" href="#_1-7-words-you-will-see" aria-label="Permalink to &quot;1.7 Words you will see&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Job</strong></td><td>One car visit. It carries the customer, vehicle, quote, work, files, invoices, payments and release.</td></tr><tr><td><strong>Nature</strong></td><td>Private, Insurance, Corporate, Government or Bidding. Decides down payment and paperwork gates.</td></tr><tr><td><strong>Job type</strong></td><td>Retail, Insurance or Fleet.</td></tr><tr><td><strong>LOA</strong></td><td>Letter of Authorization from an insurer, with an authorized amount.</td></tr><tr><td><strong>Who pays</strong></td><td>On each work line: Customer or Insurer. Drives split billing.</td></tr><tr><td><strong>Work billed / Cash in</strong></td><td>Accrual (what was invoiced) vs money actually received. The app always shows both.</td></tr><tr><td><strong>Owner override</strong></td><td>A release or gate bypass the owner records with a written reason. Always logged.</td></tr><tr><td><strong>Manila time</strong></td><td>All dates and cut-offs in the app use Asia/Manila. Dates read like &quot;Oct 29, 2026&quot;.</td></tr><tr><td><strong>Target date</strong></td><td>When the repair should be done (it used to be called &quot;Promised date&quot;).</td></tr><tr><td><strong>Appointment</strong></td><td>When the car is booked to come in. Separate from the target date.</td></tr><tr><td><strong>Released / Done</strong></td><td>Released: the car has left the shop. Done: nothing is left on the job (it used to be called Closed).</td></tr><tr><td><strong>This week</strong></td><td>Monday to Sunday, on every page with a week (Attendance, Payroll, My week).</td></tr><tr><td><strong>Margin on cost</strong></td><td>(sell − cost) ÷ cost. A ₱300 cost sold at ₱800 is 167% on cost.</td></tr></tbody></table>',41)])])}const w=e(h,[["render",l]]);export{y as __pageData,w as default};
